/* Session identity, instance notes, reference interpretation and program progression. */
function sessionDate(r){return Number.isFinite(r?.completedAt)?new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'short',year:'numeric',timeZone:'America/Toronto'}).format(r.completedAt):r?.date||'Date unavailable';}
function sessionTime(r){return Number.isFinite(r?.completedAt)?new Intl.DateTimeFormat('en-CA',{hour:'numeric',minute:'2-digit',timeZone:'America/Toronto'}).format(r.completedAt):'';}
function sessionStamp(r){return sessionDate(r)+(sessionTime(r)?' · '+sessionTime(r):'');}
function sessionNote(r){return state.reportNotes?.[reportNoteKey(r)];}
function sessionNoteTop(r){
 const note=sessionNote(r),canWrite=state.actor==='coach'&&!state.guided,key=reportNoteKey(r),draft=state.noteDrafts?.[key]??note?.text??'';
 if(!canWrite&&!note?.text)return '';
 return `<details class="session-note-top"><summary><strong>${note?.text?'Session note':'Add session note'}</strong>${note?.text?`<span>${escapeHTML(note.text)}</span>`:'<span>Positioning, effort or context for this visit</span>'}</summary><div class="session-note-editor">${canWrite?`<label class="sr-only" for="session-top-note">Note for ${escapeHTML(sessionStamp(r))}</label><textarea id="session-top-note" data-note-key="${escapeHTML(key)}" rows="3" maxlength="2000" placeholder="Add a note for this session…">${escapeHTML(draft)}</textarea><div class="button-row">${button('Save note','save-top-note','small-button')}</div>`:`<p>${escapeHTML(note.text)}</p>`}${note?`<small>Saved by ${escapeHTML(note.author)} · ${escapeHTML(note.time)}</small>`:''}</div></details>`;
}
// One-line caption of a saved note for the report header; the editor itself opens from the header Note button.
function sessionNoteLine(r){
 const note=sessionNote(r);
 return note?.text?`<p class="report-note-line"><strong>Note</strong> ${escapeHTML(note.text)}</p>`:'';
}
function saveSessionNote(r,text){
 if(!r||state.actor!=='coach'||state.guided||r.personId!==state.personId)return;
 state.reportNotes??={};state.reportNotes[reportNoteKey(r)]={text:text.trim(),author:clinician().name,time:sessionStamp({completedAt:Date.now()})};
 if(state.noteDrafts)delete state.noteDrafts[reportNoteKey(r)];render();toast('Note saved to this session.');
}
function historySelectionGrid(records){
 if(!records.length)return '<div class="history-empty"><h3>No matching sessions</h3><p>Choose another session type.</p></div>';
 const scales=historyRadarScales(memberHistoryRecords()),selected=historyCompareUI().selected;
 return `<ul class="history-grid">${records.map(r=>{const data=r.partial?null:reportData(r),metric=reportMetric(r),title=sessionRecordLabel(r)+' '+r.purpose,note=sessionNote(r);return `<li class="history-grid-card ${selected.includes(r.id)?'is-selected':''}">${comparisonCheckbox('history',r.id,r,sessionStamp(r)+', '+title)}<button class="history-grid-open" data-action="history-open-record" data-id="${escapeHTML(r.id)}" aria-label="Open ${escapeHTML(sessionStamp(r)+', '+title)}"><strong class="history-grid-date">${sessionDate(r)}</strong><span class="history-grid-time">${sessionTime(r)}</span>${historyRadar(r,scales[metric.field])}<strong>${title}</strong><small>${r.positions} directions · ${r.reps} ${r.reps===1?'rep':'reps'}</small><span class="history-grid-result">${data?data[metric.field].toFixed(1)+' <small>'+metric.unit+'</small>':'Incomplete'}</span><small>${metric.label}</small>${note?.text?`<span class="history-note-snippet">Note · ${escapeHTML(note.text)}</span>`:''}</button></li>`;}).join('')}</ul>`;
}
const symmetrySources={ufc:'https://valdperformance.com/news/neck-coupling-strength-in-mma-testing-what-matters',vald:'https://valdhealth.com/news/benchmarking-for-rehabilitation-providers',reliability:'https://pmc.ncbi.nlm.nih.gov/articles/PMC11314792/'};
function symmetrySettings(){state.symmetrySettings??={};return state.symmetrySettings[state.personId]??={reference:'none',tolerance:0};}
function symmetryReference(pair,settings=symmetrySettings()){
 if(settings.reference==='none')return null;
 if(pair.a===270&&pair.b===90)return 1;
 if(pair.a===0&&pair.b===180&&settings.reference.startsWith('ufc'))return settings.reference==='ufc-male'?.8:.7;
 return null;
}
function pairReferenceStatus(pair,settings=symmetrySettings()){
 const target=symmetryReference(pair,settings),ratio=pair.second>0?pair.first/pair.second:null;
 const gap=target&&ratio!==null?(target===1?100*(1-Math.min(pair.first,pair.second)/Math.max(pair.first,pair.second)):100*Math.abs(ratio-target)/target):null;
 return {target,ratio,gap,tone:gap===null||!settings.tolerance?'neutral':gap<=settings.tolerance?'up':'down'};
}
function symmetryPanel(r,ui){
 const data=reportData(r),settings=symmetrySettings(),prior=reportPreviousSession(r),before=prior?reportData(prior):null,selected=data.pairs[ui.pair]||data.pairs[0],readOnly=state.actor!=='coach'||state.guided;
 return `<h2>Force ratios & symmetry</h2><div class="symmetry-settings"><label>Reference<select id="symmetry-reference" ${readOnly?'disabled':''}>${[['none','No reference selected'],['bilateral','Left / right balance'],['ufc-male','UFC MMA · male reference'],['ufc-female','UFC MMA · female reference']].map(([key,label])=>`<option value="${key}" ${settings.reference===key?'selected':''}>${label}</option>`).join('')}</select></label><label>Coach alert tolerance<select id="symmetry-tolerance" ${readOnly?'disabled':''}>${[[0,'Off · values only'],[5,'5%'],[10,'10%'],[15,'15%'],[20,'20%']].map(([key,label])=>`<option value="${key}" ${settings.tolerance===key?'selected':''}>${label}</option>`).join('')}</select></label></div><div class="symmetry-list">${data.pairs.map((pair,index)=>{const status=pairReferenceStatus(pair),old=before?.pairs.find(p=>p.a===pair.a&&p.b===pair.b),oldStatus=old?pairReferenceStatus(old):null,delta=status.gap!==null&&oldStatus?.gap!==null&&oldStatus?Math.round((oldStatus.gap-status.gap)*10)/10:null;return `<button data-action="report-pair" data-pair="${index}" class="${index===ui.pair?'active':''}" aria-pressed="${index===ui.pair}"><span><strong>${pair.name}</strong><small>${pair.a}° / ${pair.b}° · ${status.target?'Reference '+status.target.toFixed(2)+':1':'No published target applied'}</small><small class="change-${status.tone}">${status.gap===null?'Descriptive only':settings.tolerance?(status.gap<=settings.tolerance?'Within coach tolerance':'Outside coach tolerance'):'Distance from target '+status.gap.toFixed(1)+'%'}${delta===null?'':` · <span class="change-${delta>0?'up':delta<0?'down':'neutral'}">${Math.abs(delta).toFixed(1)} pts ${delta>0?'closer':delta<0?'farther':'change'}</span>`}</small></span><b>${status.ratio===null?'—':status.ratio.toFixed(2)+':1'}<small>${pair.percent}% match</small></b></button>`;}).join('')}</div><div class="selected-pair-values"><span>${selected.a}° <strong>${selected.first.toFixed(1)} kg</strong></span><span>${selected.b}° <strong>${selected.second.toFixed(1)} kg</strong></span></div><details class="symmetry-evidence"><summary>Reference & threshold notes</summary><p>UFC references describe MMA athletes tested on ForceFrame. They are context, not validated Kinmetrix pass/fail thresholds. Diagonal pairs have no target applied.</p><p>A coach tolerance is an operational alert, not a scientific cutoff. Left/right gap uses (higher − lower) / higher. Flexion/extension gap uses distance from the selected ratio, divided by that ratio.</p><p>Green/red changes describe direction of change, not statistical significance. Small changes can be measurement noise; Kinmetrix repeatability limits are not established here.</p><a href="${symmetrySources.ufc}" target="_blank" rel="noopener">VALD / UFC reference ratios</a> · <a href="${symmetrySources.vald}" target="_blank" rel="noopener">VALD on asymmetry thresholds</a> · <a href="${symmetrySources.reliability}" target="_blank" rel="noopener">Neck test reliability study</a></details>`;
}
const programTargetCeilingFactor=1.02;
function programLoad(plan){const load={kind:'assessment',start:12,increase:0,percent:60,increaseKind:'percent',...plan?.load};if(!['percent','kg'].includes(load.increaseKind))load.increaseKind='percent';return load;}
function programClampTarget(kg){return Number(Math.max(1,Math.min(50,kg)).toFixed(1));}
function programLatestAssessment(personId){return [...state.history.filter(r=>r.personId===personId),...reportFixtureHistory(personId)].filter(r=>r.type==='strength'&&r.purpose==='assessment'&&!r.partial).sort((a,b)=>b.completedAt-a.completedAt)[0];}
function programAngleForce(directions,angle){const exact=directions.find(d=>d.angle===angle)?.force;if(Number.isFinite(exact))return exact;if(!directions?.length)return null;let nearest=null,minDiff=360;for(const d of directions){let diff=Math.abs(d.angle-angle);diff=Math.min(diff,360-diff);if(diff<minDiff){minDiff=diff;nearest=d.force;}}return Number.isFinite(nearest)?nearest:null;}
function programVisitForceAtAngle(record,angle){if(!record||record.partial)return null;const data=reportData(record);return data?.directions?programAngleForce(data.directions,angle):null;}
function programCompletedVisits(plan,personId,assessmentAt){const after=Number.isFinite(assessmentAt)?assessmentAt:0;return [...(plan.exampleVisits||[]).filter(r=>r.personId===personId),...state.history.filter(r=>r.personId===personId&&r.programId===plan.id)].filter(r=>!r.partial&&r.completedAt>=after).sort((a,b)=>(a.programSession||0)-(b.programSession||0)||(a.completedAt||0)-(b.completedAt||0));}
function programLinearRegression(y){const n=y.length,x=Array.from({length:n},(_,i)=>i),meanX=(n-1)/2,meanY=y.reduce((a,b)=>a+b,0)/n;let num=0,den=0;for(let i=0;i<n;i++){const xd=x[i]-meanX;num+=xd*(y[i]-meanY);den+=xd*xd;}const slope=den?num/den:0;return {slope,intercept:meanY-slope*meanX};}
function programSmartNextForce(proportion,assessmentPeak,sessionPeaks){const floor=proportion*assessmentPeak;if(!sessionPeaks.length)return programClampTarget(floor);const points=[assessmentPeak,...sessionPeaks];if(points.length<2)return programClampTarget(floor);const {slope}=programLinearRegression(points),predicted=floor+slope*points.length,lastPeak=points.at(-1),ceiling=lastPeak*programTargetCeilingFactor;if(ceiling<floor)return programClampTarget(floor);return programClampTarget(Math.min(Math.max(predicted,floor),ceiling));}
function programAssessmentDemoBase(load){const source=programLatestAssessment('alex'),force=source?programAngleForce(reportData(source).directions,0):null;return Number.isFinite(force)?Number((force*load.percent/100).toFixed(1)):12;}
function programLastSessionPreviewValues(load,total){const source=programLatestAssessment('alex'),peak=source?programAngleForce(reportData(source).directions,0):null;if(!Number.isFinite(peak))return Array.from({length:total},()=>null);const proportion=load.percent/100,values=[],sessionPeaks=[];for(let i=0;i<total;i++){const target=programSmartNextForce(proportion,peak,sessionPeaks);values.push(target);sessionPeaks.push(target*programTargetCeilingFactor);}return values;}
function programAssessmentTargetAtSession(baseKg,sessionIndex,load){if(!Number.isFinite(baseKg))return null;const step=Math.max(0,sessionIndex);return load.increaseKind==='kg'?Number((baseKg+load.increase*step).toFixed(1)):Number((baseKg*(1+load.increase/100)**step).toFixed(1));}
function programLoadLabel(plan){const load=programLoad(plan);if(load.kind==='assessment')return load.increase>0?`${load.percent}% of latest strength · +${load.increase}${load.increaseKind==='kg'?' kg':'%'} / session`:`${load.percent}% of latest strength · per angle`;if(load.kind==='last-session')return `${load.percent}% smart progression · per angle`;return load.kind==='incremental'?`${load.start} kg start · +${load.increase}% / session`:`${load.start} kg · fixed`;}
function programProgressionFields(draft,prefix){const load=programLoad(draft);return `<fieldset class="program-progression" data-prefix="${prefix}"><legend>Target progression</legend><label>Target method<select id="${prefix}-load-kind" data-load-kind="${prefix}">${[['fixed','Fixed target'],['incremental','Increase each session'],['assessment','% of latest strength assessment'],['last-session','% of last session (smart)']].map(([value,label])=>`<option value="${value}" ${load.kind===value?'selected':''}>${label}</option>`).join('')}</select></label><div data-load-inputs>${programLoadInputs(load,prefix)}</div><div class="program-load-preview" id="${prefix}-load-preview">${programLoadPreview(load,Number(draft.total)||6)}</div></fieldset>`;}
function programLoadInputs(load,prefix){if(load.kind==='last-session')return `<div class="program-form-grid"><label>Session percentage<div class="program-unit-input"><input id="${prefix}-load-percent" type="number" required min="1" max="100" step="1" value="${load.percent}" data-load-preview="${prefix}"><span>%</span></div></label></div><p class="program-form-note">Session 1 targets come from the latest complete isometric assessment × session percentage. Later sessions use smart progression from this program’s completed sessions (regression with a 1.02× ceiling on the last session peak). Partial sessions do not advance progression.</p>`;return load.kind==='assessment'?`<div class="program-form-grid"><label>Assessment percentage<div class="program-unit-input"><input id="${prefix}-load-percent" type="number" required min="1" max="100" step="1" value="${load.percent}" data-load-preview="${prefix}"><span>%</span></div></label><div class="program-increase-pair"><label>Increase type<select id="${prefix}-load-increase-kind" data-load-increase-kind="${prefix}">${[['percent','Percent per session'],['kg','Kilograms per session']].map(([value,label])=>`<option value="${value}" ${load.increaseKind===value?'selected':''}>${label}</option>`).join('')}</select></label><label>Increase each session<div class="program-unit-input"><input id="${prefix}-load-increase" type="number" required min="0" max="${load.increaseKind==='kg'?50:100}" step="${load.increaseKind==='kg'?0.1:0.1}" value="${load.increase}" data-load-preview="${prefix}"><span>${load.increaseKind==='kg'?'kg':'%'}</span></div></label></div></div><p class="program-form-note">Uses each angle’s peak force from the latest complete Isometric assessment as the base. Completed sessions advance targets by the increase you choose. Partial sessions do not advance progression.</p>`:`<div class="program-form-grid"><label>${load.kind==='fixed'?'Target':'Starting target'}<div class="program-unit-input"><input id="${prefix}-load-start" type="number" required min="1" max="50" step="0.1" value="${load.start}" data-load-preview="${prefix}"><span>kg</span></div></label>${load.kind==='incremental'?`<label>Increase each session<div class="program-unit-input"><input id="${prefix}-load-increase" type="number" required min="0" max="100" step="0.1" value="${load.increase}" data-load-preview="${prefix}"><span>%</span></div></label>`:''}</div><p class="program-form-note">${load.kind==='fixed'?'Same target in every direction and session.':'Each completed session advances the target. Increases compound from the starting target; partial sessions do not advance it.'}</p>`;}
function readProgramLoad(prefix){const kind=$('#'+prefix+'-load-kind').value;return {kind,start:Number($('#'+prefix+'-load-start')?.value??12),increase:kind==='last-session'?0:Number($('#'+prefix+'-load-increase')?.value??0),percent:Number($('#'+prefix+'-load-percent')?.value??60),increaseKind:$('#'+prefix+'-load-increase-kind')?.value||'percent'};}
function programLoadPreview(load,total){if(load.kind==='assessment'){const base=programAssessmentDemoBase(load);return `<span>Session targets · kg (demo · 0°)</span><ol>${Array.from({length:total},(_,i)=>{const value=programAssessmentTargetAtSession(base,i,load);return `<li><small>${i+1}</small><strong class="${value>50?'change-down':''}">${Number.isFinite(value)?value.toFixed(1):'—'}</strong></li>`;}).join('')}</ol>`;}if(load.kind==='last-session')return `<span>Session targets · kg (demo · 0° · approximate)</span><ol>${programLastSessionPreviewValues(load,total).map((value,i)=>`<li><small>${i+1}</small><strong class="${value>50?'change-down':''}">${Number.isFinite(value)?value.toFixed(1):'—'}</strong></li>`).join('')}</ol>`;return `<span>Session targets · kg</span><ol>${Array.from({length:total},(_,i)=>{const value=load.start*(load.kind==='incremental'?(1+load.increase/100)**i:1);return `<li><small>${i+1}</small><strong class="${value>50?'change-down':''}">${Number.isFinite(value)?value.toFixed(1):'—'}</strong></li>`;}).join('')}</ol>`;}
function validProgramLoad(load,total){if(!['fixed','incremental','assessment','last-session'].includes(load.kind)||!Number.isFinite(load.percent))return false;if(load.kind==='last-session'){if(load.percent<1||load.percent>100)return false;const last=programLastSessionPreviewValues(load,total).at(-1);return Number.isFinite(last)&&last>=1&&last<=50;}if(!Number.isFinite(load.start)||!Number.isFinite(load.increase))return false;if(load.kind==='assessment'){if(load.percent<1||load.percent>100||load.increase<0||!['percent','kg'].includes(load.increaseKind))return false;if(!load.increase)return true;const base=programAssessmentDemoBase(load),last=programAssessmentTargetAtSession(base,total-1,load);return Number.isFinite(last)&&last>=1&&last<=50&&(load.increaseKind==='percent'?load.increase<=100:load.increase<=50);}return load.start>=1&&load.start<=50&&load.increase>=0&&load.increase<=100&&(load.kind!=='incremental'||load.start*(1+load.increase/100)**(total-1)<=50);}
function validateProgramLoadForm(prefix,total){const load=readProgramLoad(prefix),field=$('#'+prefix+'-load-kind');field.setCustomValidity(validProgramLoad(load,total)?'':'All session targets must stay between 1 and 50 kg. Adjust the starting target or increase.');field.reportValidity();return validProgramLoad(load,total)?load:null;}
function resolveProgramTargets(plan,personId,positions=plan.positions){
 const load=programLoad(plan),angles=Array.from({length:positions},(_,i)=>i*360/positions),index=plan.completed||0;
 if(load.kind==='last-session'){
  const assessment=programLatestAssessment(personId),directions=assessment?reportData(assessment).directions:[],assessmentAt=assessment?.completedAt??0;
  const visits=programCompletedVisits(plan,personId,assessmentAt).filter(r=>(r.programSession||0)<=index);
  const prior=index>0?visits.filter(r=>r.programSession===index).at(-1):null;
  const targets=Object.fromEntries(angles.map(a=>{const peak=programAngleForce(directions,a);if(!Number.isFinite(peak))return [a,null];const sessionPeaks=visits.map(r=>programVisitForceAtAngle(r,a)).filter(Number.isFinite);return [a,programSmartNextForce(load.percent/100,peak,sessionPeaks)];}));
  const source=index===0?(assessment?{id:assessment.id,completedAt:assessment.completedAt,date:assessment.date}:null):(prior?{id:prior.id,completedAt:prior.completedAt,date:prior.date,programSession:prior.programSession}:null);
  return {targets,source,load};
 }
 if(load.kind!=='assessment'){const target=Number((load.start*(load.kind==='incremental'?(1+load.increase/100)**index:1)).toFixed(1));return {targets:Object.fromEntries(angles.map(a=>[a,target])),source:null,load};}
 const source=programLatestAssessment(personId),directions=source?reportData(source).directions:[],targets=Object.fromEntries(angles.map(a=>{const force=directions.find(d=>d.angle===a)?.force,base=Number.isFinite(force)?Number((force*load.percent/100).toFixed(1)):null;return [a,programAssessmentTargetAtSession(base,index,load)];}));
 return {targets,source:source?{id:source.id,completedAt:source.completedAt,date:source.date}:null,load};
}
function initializeProgramTargets(plan){if(!plan)return;const resolved=resolveProgramTargets(plan,state.personId);Object.assign(state.setup,{programLoad:resolved.load,programSource:resolved.source,targets:resolved.targets,weight:resolved.targets[0]??1});}
function programProgressSourceLabel(cfg){if(!cfg.programSource)return '';return cfg.programSource.programSession?`Program session ${cfg.programSource.programSession} · ${sessionStamp(cfg.programSource)}`:`Assessment · ${sessionStamp(cfg.programSource)}`;}
function programSetupPanel(){const cfg=state.setup;if(!cfg.programLoad)return '';const missing=currentAngles().some(a=>!Number.isFinite(cfg.targets?.[a])),kind=cfg.programLoad.kind,sessionNum=cfg.programSession||1,needAssessment=missing&&(kind==='assessment'||(kind==='last-session'&&sessionNum===1)),needPrior=missing&&kind==='last-session'&&sessionNum>1;return `<section class="program-setup-targets"><div><h2>Session ${cfg.programSession} target</h2><p>${programLoadLabel({load:cfg.programLoad})}${cfg.programSource?' · '+programProgressSourceLabel(cfg):''}</p></div>${needAssessment?'<p class="change-down">A complete strength assessment covering every selected angle is required before starting.</p>':needPrior?'<p class="change-down">Complete the previous program session before starting this one.</p>':missing?'<p class="change-down">Targets are not available for every selected angle.</p>':''}<div class="program-target-angles">${currentAngles().map(a=>`<span>${a}° <strong>${Number.isFinite(cfg.targets?.[a])?cfg.targets[a].toFixed(1)+' kg':'Not measured'}</strong></span>`).join('')}</div></section>`;}
function programTargetsValid(){const cfg=state.setup;return !cfg.programLoad||currentAngles().every(a=>Number.isFinite(cfg.targets?.[a])&&cfg.targets[a]>=1&&cfg.targets[a]<=50);}
function activateProgramTarget(angle){const cfg=state.setup;if(!cfg.programLoad||!Number.isFinite(cfg.targets?.[angle]))return;cfg.weight=cfg.targets[angle];setupModeDefaults();}
function recordTarget(r,angle){return r.sessionSettings?.targets?.[angle]??r.weight??12;}
const sessionToolActions={'save-top-note':()=>saveSessionNote(state.stage==='review'?state.result:overviewResult(),$('#session-top-note').value)};
document.addEventListener('input',event=>{const el=event.target;if(el.dataset.noteKey){state.noteDrafts??={};state.noteDrafts[el.dataset.noteKey]=el.value;}const prefix=el.dataset.loadPreview;if(prefix){$('#'+prefix+'-load-kind').setCustomValidity('');$('#'+prefix+'-load-preview').innerHTML=programLoadPreview(readProgramLoad(prefix),Number($('#'+prefix+'-total').value));}});
document.addEventListener('change',event=>{const el=event.target;
 if(el.id==='symmetry-reference'||el.id==='symmetry-tolerance'){if(state.actor!=='coach'||state.guided)return;const s=symmetrySettings();if(el.id==='symmetry-reference')s.reference=el.value;else s.tolerance=Number(el.value);render();$('#'+el.id)?.focus({preventScroll:true});}
 if(el.dataset.loadKind||el.dataset.loadIncreaseKind){const prefix=el.dataset.loadKind||el.dataset.loadIncreaseKind,fieldset=el.closest('fieldset'),load=readProgramLoad(prefix);fieldset.querySelector('[data-load-inputs]').innerHTML=programLoadInputs(load,prefix);$('#'+prefix+'-load-preview').innerHTML=programLoadPreview(load,Number($('#'+prefix+'-total').value));}
 if(['plan-total','program-total'].includes(el.id)){const prefix=el.id.split('-')[0];$('#'+prefix+'-load-kind').setCustomValidity('');$('#'+prefix+'-load-preview').innerHTML=programLoadPreview(readProgramLoad(prefix),Number(el.value));}
});

function sessionProgramSummary(r){const cfg=r.sessionSettings;if(!cfg?.programLoad)return '';return `<details class="session-program-summary"><summary>Program target · Session ${cfg.programSession} of ${cfg.programTotal} · ${programLoadLabel({load:cfg.programLoad})}</summary><p>${cfg.programSource?programProgressSourceLabel(cfg):'Targets from the program schedule'}. Saved for this session.</p><div class="program-target-angles">${Object.entries(cfg.targets||{}).map(([a,value])=>`<span>${a}° <strong>${Number(value).toFixed(1)} kg</strong></span>`).join('')}</div></details>`;}
function programExportRows(r,unit='kg'){const cfg=r.sessionSettings;if(!cfg?.programLoad)return [];const source=cfg.programSource?(cfg.programSource.programSession?`Program session ${cfg.programSource.programSession} · ${sessionStamp(cfg.programSource)}`:`Assessment · ${sessionStamp(cfg.programSource)}`):'None';return [[],['Program',r.programName],['Program session',cfg.programSession],['Progression',programLoadLabel({load:cfg.programLoad})],['Target source',source],['Target angle','Target ('+exportForceUnits[unit].label+')'],...Object.entries(cfg.targets).map(([a,value])=>[a,exportForce(value,unit)])];}
